222	    /**
223	     * Resolves the city name to use for a newly created owner. The supplied city is
224	     * title-cased (each whitespace-separated word starts with an upper-case letter and the
225	     * remaining letters are lower-cased), for example {@code "new york"} becomes
226	     * {@code "New York"}. However, if an owner already exists in that city (matched ignoring
227	     * letter case), the existing owner's exact spelling of the city name is reused instead, so
228	     * that all owners in a city share a single canonical spelling.
229	     *
230	     * @param city the city supplied for the owner being created, may be {@code null}
231	     * @return the city name to store and return for the owner
232	     */
233	    private String resolveCity(String city) {
234	        if (city == null) {
235	            return null;
236	        }
237	        String existingCity = this.clinicService.findAllOwners().stream()
238	            .map(Owner::getCity)
239	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
240	            .findFirst()
241	            .orElse(null);
242	        if (existingCity != null) {
243	            return existingCity;
244	        }
245	        return toTitleCase(city);
246	    }
