248	    /**
249	     * Title-cases the given text so that each whitespace-separated word starts with an
250	     * upper-case letter and the remaining letters are lower-cased, for example
251	     * {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}. The original
252	     * spacing between words is preserved.
253	     *
254	     * @param value the text to title-case
255	     * @return the title-cased text
256	     */
257	    private static String toTitleCase(String value) {
258	        StringBuilder result = new StringBuilder(value.length());
259	        boolean startOfWord = true;
260	        for (int i = 0; i < value.length(); i++) {
261	            char ch = value.charAt(i);
262	            if (Character.isWhitespace(ch)) {
263	                startOfWord = true;
264	                result.append(ch);
265	            } else if (startOfWord) {
266	                result.append(Character.toUpperCase(ch));
267	                startOfWord = false;
268	            } else {
269	                result.append(Character.toLowerCase(ch));
270	            }
271	        }
272	        return result.toString();
273	    }
