275	    /**
276	     * Builds the customer code for a newly created owner, formatted as
277	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
278	     * owners already registered in that city, zero-padded to four digits (e.g.
279	     * {@code 'LONDON-0007'}). Cities are matched ignoring letter case so the sequence is
280	     * consistent with the upper-cased prefix.
281	     *
282	     * @param city the city of the owner being created
283	     * @return the assigned customer code
284	     */
285	    private String nextCustomerCode(String city) {
286	        long ownersInCity = this.clinicService.findAllOwners().stream()
287	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
288	            .count();
289	        return city.toUpperCase() + "-" + String.format("%04d", ownersInCity + 1);
290	    }
