292	    /**
293	     * Determines whether the maximum number of owners that may be registered on a single day has
294	     * already been reached. At most 20 owners may be created per day; the count is taken over the
295	     * owners whose registration date is today.
296	     *
297	     * @return {@code true} if 20 or more owners have already been registered today
298	     */
299	    private boolean isDailyRegistrationLimitReached() {
300	        LocalDate today = LocalDate.now();
301	        long ownersToday = this.clinicService.findAllOwners().stream()
302	            .filter(existing -> today.equals(existing.getRegistrationDate()))
303	            .count();
304	        return ownersToday >= 20;
305	    }
