307	    /**
308	     * Determines whether the city of the owner being created has already reached its capacity of
309	     * owners. At most 8 owners may be registered in a single city; the count is taken over the
310	     * existing owners whose city matches (ignoring letter case) the given city.
311	     *
312	     * @param city the city of the owner being created, may be {@code null}
313	     * @return {@code true} if the city already contains 8 or more owners
314	     */
315	    private boolean isCityCapacityReached(String city) {
316	        if (city == null) {
317	            return false;
318	        }
319	        long ownersInCity = this.clinicService.findAllOwners().stream()
320	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
321	            .count();
322	        return ownersInCity >= 8;
323	    }
