325	    /**
326	     * Determines whether an owner already exists that uses the same telephone number as the
327	     * given candidate. Telephone numbers are compared digits-only, so formatting characters
328	     * such as spaces, dashes and parentheses are ignored.
329	     *
330	     * @param owner the candidate owner to check
331	     * @return {@code true} if an owner with the same telephone number already exists
332	     */
333	    private boolean isDuplicateOwner(Owner owner) {
334	        String telephone = normalizeTelephone(owner.getTelephone());
335	        return this.clinicService.findAllOwners().stream()
336	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
337	    }
338	
339	    /**
340	     * Determines whether an owner already exists that uses the same email address as the
341	     * given candidate. Owners without an email address are never considered duplicates.
342	     * The comparison ignores letter case and surrounding or repeated whitespace.
343	     *
344	     * @param owner the candidate owner to check
345	     * @return {@code true} if an owner with the same email address already exists
346	     */
347	    private boolean isDuplicateEmail(Owner owner) {
348	        String email = normalize(owner.getEmail());
349	        if (email == null || email.isEmpty()) {
350	            return false;
351	        }
352	        return this.clinicService.findAllOwners().stream()
353	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
354	    }
355	
356	    /**
357	     * Normalizes a value for duplicate detection so that comparisons ignore letter case and
358	     * surrounding or repeated whitespace. Leading and trailing whitespace is stripped, any run
359	     * of internal whitespace collapses to a single space, and the result is lower-cased. For
360	     * example {@code "  John   Smith "} and {@code "John Smith"} both normalize to
361	     * {@code "john smith"}.
362	     *
363	     * @param value the value to normalize, may be {@code null}
364	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
365	     */
366	    private static String normalize(String value) {
367	        if (value == null) {
368	            return null;
369	        }
370	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
371	    }
372	
373	    /**
374	     * Normalizes a telephone number to digits only by stripping every non-digit character
375	     * (such as spaces, dashes and parentheses). This is used both to store telephone numbers
376	     * in a canonical form and to compare them for uniqueness, so that {@code "(613) 555-0100"}
377	     * and {@code "6135550100"} are treated as the same number.
378	     *
379	     * @param value the telephone number to normalize, may be {@code null}
380	     * @return the digits-only telephone number, or {@code null} if {@code value} is {@code null}
381	     */
382	    private static String normalizeTelephone(String value) {
383	        if (value == null) {
384	            return null;
385	        }
386	        return value.replaceAll("\\D", "");
387	    }
